// Zusammenhang: BackupTests.swift, ImportTests.swift, Sources/ParalistCore/Backup/Zip.swift
import Foundation
@testable import ParalistCore

enum ZipFixtures {
    static let androidDeflate = Data(base64Encoded: "")!
    static let deflateBomb = Data(base64Encoded: "")!
    static let randomBytes = Data(base64Encoded: "")!

    static func zip(_ entries: [(String, Data)]) -> URL {
        let url = temporaryDirectory().appendingPathComponent("test.zip")
        let writer = try! ZipWriter(url: url)
        for (name, data) in entries { try! writer.add(name, data) }
        try! writer.finish()
        return url
    }

    static func write(_ data: Data) -> URL {
        let url = temporaryDirectory().appendingPathComponent("test.zip")
        try! data.write(to: url)
        return url
    }

    static func markSymlink(_ url: URL, _ name: String) -> URL {
        var bytes = [UInt8](try! Data(contentsOf: url))
        let nameBytes = [UInt8](name.utf8)
        for i in 0..<(bytes.count - 46) where bytes[i] == 0x50 && bytes[i + 1] == 0x4B && bytes[i + 2] == 0x01 && bytes[i + 3] == 0x02 {
            let length = Int(bytes[i + 28]) | Int(bytes[i + 29]) << 8
            guard length == nameBytes.count, Array(bytes[(i + 46)..<(i + 46 + length)]) == nameBytes else { continue }
            bytes[i + 4] = 20
            bytes[i + 5] = 3
            bytes[i + 38] = 0; bytes[i + 39] = 0; bytes[i + 40] = 0xFF; bytes[i + 41] = 0xA1
        }
        try! Data(bytes).write(to: url)
        return url
    }

    static func entry(_ id: String, _ title: String, updated: String = "2026-10-10T10:00:00Z", extra: String = "") -> (String, Data) {
        ("eintraege/\(id).md", Data("---\nid: \(id)\ntyp: notiz\ntitel: \"\(title)\"\nerstellt: 2026-10-01T10:00:00Z\ngeaendert: \(updated)\norte: []\n\(extra)---\nText\n".utf8))
    }
}
